<?php
declare(strict_types=1);

namespace Hardness\Observability\Collectors\Mysql;

/** Produz diagnósticos determinísticos usando somente o contrato histórico autorizado. */
final class MysqlRecorderDiagnosticEngine
{
    private const MAX_DIAGNOSTICS = 200;

    public function diagnose(array $timeline, array $status, array $errors, array $digests, array $metadata, array $period): array
    {
        $result = array();
        foreach ($timeline as $event) {
            $details=is_array($event['details']??null)?$event['details']:array();
            $common=$this->common((string)($event['schema']??''),(string)($event['at']??''),$period,!empty($event['synthetic']));
            if (($event['type']??'')==='lock' && !empty($details['confirmed'])) {
                $result[]=$this->item('confirmed','lock_confirmed',$common,'Lock confirmado entre sessões','O MySQL registrou uma relação direta entre a sessão bloqueada e a bloqueadora.',array('waiting_process_id'=>(int)($details['waiting_process_id']??0),'blocking_process_id'=>(int)($details['blocking_process_id']??0),'waiting_seconds'=>(int)($details['waiting_seconds']??0),'blocking_seconds'=>(int)($details['blocking_seconds']??0),'object'=>(string)($details['object']??''),'index'=>(string)($details['index']??''),'lock_type'=>(string)($details['lock_type']??''),'requested_mode'=>(string)($details['requested_mode']??''),'blocking_mode'=>(string)($details['blocking_mode']??''),'waiting_state'=>(string)($details['waiting_state']??''),'blocking_state'=>(string)($details['blocking_state']??'')),'Verificar a transação bloqueadora e o fluxo que mantém o lock; não encerrar sessões sem avaliar impacto.','A relação de lock é confirmada, mas os dados não determinam por que a transação permaneceu aberta.',$this->lockSql($details));
            } elseif (($event['type']??'')==='long_query') {
                $result[]=$this->item('confirmed','long_query',$common,'Consulta longa observada','A consulta permaneceu ativa pelo tempo registrado na amostra.',array('duration_seconds'=>(int)($event['duration_seconds']??0),'process_id'=>(int)($details['process_id']??0),'state'=>(string)($details['state']??''),'waiting_for_lock'=>!empty($details['waiting_for_lock']),'tables'=>array_values(array_filter($details['tables']??array(),'is_string'))),'Revisar o plano e as condições da execução em ambiente seguro; nenhuma análise adicional foi executada automaticamente.','A duração é confirmada, mas a amostra isolada não confirma a causa.',$this->sql($details,array('query')));
            } elseif (($event['type']??'')==='long_transaction') {
                $result[]=$this->item('confirmed','long_transaction',$common,'Transação longa observada','A transação estava aberta há mais tempo que o limite da coleta.',array('transaction_id'=>(string)($details['transaction_id']??''),'process_id'=>(int)($details['process_id']??0),'age_seconds'=>(int)($event['duration_seconds']??0),'state'=>(string)($details['state']??''),'process_state'=>(string)($details['process_state']??''),'started_at'=>(string)($details['started_at']??''),'wait_started_at'=>(string)($details['wait_started_at']??''),'rows_locked'=>(int)($details['rows_locked']??0),'rows_modified'=>(int)($details['rows_modified']??0),'tables_locked'=>(int)($details['tables_locked']??0)),'Investigar o ciclo de commit/rollback da aplicação e confirmar se a sessão ainda está ativa.','Transação longa não significa que ela bloqueou outra sessão; isso exige uma relação de lock registrada.',$this->sql($details,array('query')));
            }
        }
        foreach ($status as $point) {
            $delta=is_array($point['delta']??null)?$point['delta']:array(); $gauges=is_array($point['gauges']??null)?$point['gauges']:array();
            $common=$this->common((string)($point['schema']??''),(string)($point['at']??''),$period,!empty($point['synthetic']));
            if ((float)($delta['Slow_queries']??0)>0) {
                $candidates=array(); foreach(array_slice($digests,0,5) as $digest){$candidates[]=array('schema'=>$digest['schema']??'','fingerprint'=>$digest['fingerprint']??'','candidate_only'=>true);}
                $result[]=$this->item('attention','slow_queries_growth',$common,'Aumento do contador global de consultas lentas','O contador global Slow_queries aumentou. Ele não identifica individualmente quais consultas foram lentas.',array('slow_queries'=>(float)$delta['Slow_queries'],'candidates_observed_same_period'=>$candidates),'Cruzar o horário com o slow log autorizado e investigar separadamente os candidatos observados no período.','Os digests listados são apenas candidatos no mesmo período; não existe correlação confirmada com o contador global.',array());
            }
            $connected=(float)($gauges['Threads_connected']??0); $running=(float)($gauges['Threads_running']??0);
            if($running>=10||($connected>=5&&$running/$connected>=0.8)){$result[]=$this->item('strong_indication','connection_pressure',$common,'Indício de pressão de conexões','A quantidade de threads em execução está elevada em relação às conexões observadas.',array('threads_connected'=>$connected,'threads_running'=>$running),'Comparar com max_connections, latência e uma série temporal antes de ajustar qualquer parâmetro.','Sem max_connections e uma linha de base, não é possível confirmar saturação.',array());}
        }
        foreach($errors as $error){$raised=(float)($error['delta']['raised']??0);if($raised<=0){continue;}$common=$this->common((string)($error['schema']??''),(string)($error['at']??''),$period,!empty($error['synthetic']));$result[]=$this->item('attention','mysql_errors_growth',$common,'Aumento de erros MySQL','O contador do erro MySQL aumentou entre duas leituras válidas.',array('error_number'=>(int)($error['number']??0),'error_name'=>(string)($error['name']??''),'raised'=>$raised,'handled'=>(float)($error['delta']['handled']??0)),'Correlacionar o horário com logs autorizados e com o fluxo da aplicação.','O contador confirma ocorrências, mas não identifica sozinho a consulta ou a causa.',array());}
        foreach($digests as $digest){$this->digestDiagnostics($result,$digest,$period);}
        if(!empty($metadata['partial'])||!empty($metadata['unavailable_sources'])||!empty($metadata['no_data_categories'])){$result[]=$this->item('insufficient_data','collection_limited',$this->common('authorized_scope',(string)($period['to']??''),$period,!empty($metadata['synthetic'])),'Coleta insuficiente para conclusão completa','Uma ou mais fontes estão ausentes, parciais ou limitadas.',array('unavailable_categories'=>array_values(array_map(function(array $source):string{return (string)($source['category']??'');},$metadata['unavailable_sources']??array())),'no_data_categories'=>array_values($metadata['no_data_categories']??array()),'limits_reached'=>array_keys($metadata['limits_reached']??array())),'Restabelecer as fontes e repetir a observação antes de concluir ausência ou causa de problema.','Ausência de evento no histórico não prova ausência de problema.',array());}
        elseif($result===array()){$result[]=$this->item('insufficient_data','no_actionable_evidence',$this->common('authorized_scope',(string)($period['to']??''),$period,!empty($metadata['synthetic'])),'Sem evidência suficiente para diagnóstico','Não houve evento ou variação que ultrapassasse os critérios determinísticos.',array(),'Continuar a coleta e investigar o intervalo exato em que a lentidão foi percebida.','Ausência de evento coletado não significa ausência de problema.',array());}
        $weight=array('confirmed'=>4,'strong_indication'=>3,'attention'=>2,'insufficient_data'=>1);usort($result,function(array $a,array $b)use($weight):int{return($weight[$b['level']]??0)<=>($weight[$a['level']]??0);});
        if(count($result)>self::MAX_DIAGNOSTICS){$limited=array_slice($result,0,self::MAX_DIAGNOSTICS);foreach(array_reverse($result) as $item){if($item['level']==='insufficient_data'){$limited[self::MAX_DIAGNOSTICS-1]=$item;break;}}$result=$limited;}
        return $result;
    }

    private function digestDiagnostics(array &$result,array $digest,array $period):void
    {
        $m=is_array($digest['metrics']??null)?$digest['metrics']:array();$exec=(float)($m['executions']??0);if($exec<=0){return;}$common=$this->common((string)($digest['schema']??''),(string)($digest['last_seen']??($period['to']??'')),$period,!empty($digest['synthetic']));$sql=$this->sql($digest,array('sql'));
        if((float)($m['total_time_ms']??0)>=1000||(float)($m['average_time_ms']??0)>=100){$result[]=$this->item('strong_indication','digest_time',$common,'Digest com tempo relevante','O digest concentrou tempo total ou médio relevante no período.',array('executions'=>$exec,'total_time_ms'=>(float)($m['total_time_ms']??0),'average_time_ms'=>(float)($m['average_time_ms']??0),'maximum_time_ms'=>(float)($m['maximum_time_ms']??0),'maximum_time_scope'=>(string)($m['maximum_time_scope']??'accumulated_observation')),'Revisar o plano em ambiente seguro e comparar com volume e concorrência.','Tempo relevante prioriza a investigação, mas não confirma a causa.',$sql);}
        $per=(float)($m['rows_examined_per_execution']??0);if($per>=1000){$result[]=$this->item('strong_indication','rows_examined_per_execution',$common,'Muitas linhas examinadas por execução','Cada execução examinou, em média, um volume elevado de linhas.',array('executions'=>$exec,'rows_examined'=>(float)($m['rows_examined']??0),'rows_examined_per_execution'=>$per),'Investigar filtros, cardinalidade e plano em ambiente seguro.','O volume não prova sozinho falta de índice ou plano inadequado.',$sql);}
        $ratio=$m['examined_to_returned_ratio']??null;if($ratio!==null&&(float)$ratio>=100&&(float)($m['rows_examined']??0)>=1000){$result[]=$this->item('strong_indication','examined_returned_ratio',$common,'Muitas linhas examinadas para poucas retornadas','A razão entre linhas examinadas e retornadas foi elevada.',array('rows_examined'=>(float)($m['rows_examined']??0),'rows_returned'=>(float)($m['rows_returned']??0),'examined_to_returned_ratio'=>(float)$ratio),'Validar seletividade, filtros e plano em ambiente seguro.','A razão é um indício; não determina qual mudança seria segura.',$sql);}
        if((float)($m['no_index_used']??0)>0||(float)($m['no_good_index_used']??0)>0){$result[]=$this->item('attention','index_usage',$common,'Execuções sem índice adequado','O Performance Schema registrou execuções sem índice ou sem um bom índice.',array('no_index_used'=>(float)($m['no_index_used']??0),'no_good_index_used'=>(float)($m['no_good_index_used']??0),'executions'=>$exec),'Investigar o plano e a seletividade; não criar índice sem validar escrita, espaço e demais consultas.','Este sinal é indício de investigação, não uma recomendação automática de criar índice.',$sql);}
        if((float)($m['temporary_disk_tables']??0)>0){$result[]=$this->item('attention','temporary_disk_tables',$common,'Temporárias em disco observadas','O digest criou tabelas temporárias em disco no período.',array('temporary_tables'=>(float)($m['temporary_tables']??0),'temporary_disk_tables'=>(float)($m['temporary_disk_tables']??0),'executions'=>$exec),'Investigar agrupamentos, ordenações, tipos de coluna e plano antes de alterar limites do MySQL.','A métrica não identifica sozinha a causa nem justifica alterar parâmetros.',$sql);}
        if((float)($m['lock_time_ms']??0)>=100){$result[]=$this->item('strong_indication','digest_lock_time',$common,'Tempo relevante aguardando locks','O digest acumulou tempo de espera por locks no período.',array('lock_time_ms'=>(float)$m['lock_time_ms'],'executions'=>$exec),'Correlacionar com locks confirmados e transações no mesmo intervalo.','Tempo de lock no digest não identifica por si só a sessão bloqueadora.',$sql);}
    }
    private function common(string $schema,string $at,array $period,bool $synthetic):array{return array('schema'=>$schema,'at'=>$at,'period'=>$period,'synthetic'=>$synthetic);}
    private function item(string $level,string $category,array $common,string $title,string $explanation,array $evidence,string $recommendation,string $limitations,array $sql):array{return array_merge(array('level'=>$level,'category'=>$category,'schema'=>$common['schema'],'title'=>$title,'explanation'=>$explanation,'evidence'=>$evidence,'recommendation'=>$recommendation,'limitations'=>$limitations,'at'=>$common['at'],'period'=>$common['period'],'synthetic'=>$common['synthetic']),$sql);}
    private function lockSql(array $source):array{$result=array();foreach(array('waiting'=>'blocked','blocking'=>'blocker') as $sourcePrefix=>$publicPrefix){foreach(array('query'=>'sql','query_summary'=>'sql_summary','fingerprint'=>'fingerprint') as $suffix=>$publicSuffix){$field=$sourcePrefix.'_'.$suffix;if(isset($source[$field])){$result[$publicPrefix.'_'.$publicSuffix]=(string)$source[$field];break;}}}return $result;}
    private function sql(array $source,array $prefixes):array{foreach($prefixes as $prefix){if($prefix==='sql'){$field='sql';$summary='sql_summary';$fingerprint='fingerprint';}elseif($prefix==='query'){$field='query';$summary='query_summary';$fingerprint='fingerprint';}else{$field=$prefix.'_query';$summary=$prefix.'_query_summary';$fingerprint=$prefix.'_fingerprint';}if(isset($source[$field])){return array('sql'=>(string)$source[$field]);}if(isset($source[$summary])){return array('sql_summary'=>(string)$source[$summary]);}if(isset($source[$fingerprint])){return array('fingerprint'=>(string)$source[$fingerprint]);}}return array();}
}
